{
  "decision-midnight-course-hold-credit": "WITH intervals AS (SELECT squad, leg_no, start_s + CASE WHEN start_s < 43200 THEN 86400 ELSE 0 END AS s, finish_s + CASE WHEN finish_s < 43200 THEN 86400 ELSE 0 END AS f, begin_s + CASE WHEN begin_s < 43200 THEN 86400 ELSE 0 END AS b, resume_s + CASE WHEN resume_s < 43200 THEN 86400 ELSE 0 END AS r FROM leg_log CROSS JOIN course_hold WHERE finish_s IS NOT NULL), credits AS (SELECT squad, leg_no, f - s AS elapsed_s, max(0, min(f, r) - max(s, b)) AS credit_s FROM intervals) SELECT squad, leg_no, credit_s, elapsed_s - credit_s AS adjusted_s FROM credits ORDER BY squad COLLATE BINARY ASC, leg_no ASC",
  "decision-milestone-order-count": "WITH RECURSIVE orders(path) AS (SELECT '' UNION ALL SELECT o.path || m.milestone_id FROM orders AS o CROSS JOIN milestones AS m WHERE instr(o.path, m.milestone_id) = 0 AND NOT EXISTS (SELECT 1 FROM dependencies AS d WHERE d.after_id = m.milestone_id AND instr(o.path, d.before_id) = 0)) SELECT count(*) AS ordering_count FROM orders WHERE length(path) = (SELECT count(*) FROM milestones)",
  "decision-minimize-two-cycle-sensor-drift": "WITH permutations AS (SELECT a.step_code || b.step_code || c.step_code AS sequence, a.drift_microvolts AS first_drift, a.drift_microvolts + b.drift_microvolts AS second_drift, a.drift_microvolts + b.drift_microvolts + c.drift_microvolts AS cycle_drift FROM calibration_step AS a CROSS JOIN calibration_step AS b CROSS JOIN calibration_step AS c WHERE a.step_code <> b.step_code AND a.step_code <> c.step_code AND b.step_code <> c.step_code) SELECT sequence, max(abs(first_drift), abs(second_drift), abs(cycle_drift), abs(cycle_drift + first_drift), abs(cycle_drift + second_drift), abs(2 * cycle_drift)) AS peak_microvolts FROM permutations ORDER BY peak_microvolts ASC, sequence COLLATE BINARY ASC LIMIT 1",
  "decision-minimum-maintenance-vertex-cover": "WITH RECURSIVE subsets(mask, size, last_bit) AS (SELECT 0, 0, 0 UNION ALL SELECT s.mask | p.tie_bit, s.size + 1, p.tie_bit FROM subsets AS s JOIN access_points AS p ON p.tie_bit > s.last_bit), links AS (SELECT p.tie_bit | v.tie_bit AS endpoints FROM maintenance_links AS l JOIN access_points AS p ON p.point_name = l.pump_name JOIN access_points AS v ON v.point_name = l.valve_name), best AS (SELECT s.mask FROM subsets AS s WHERE NOT EXISTS (SELECT 1 FROM links AS l WHERE (s.mask & l.endpoints) = 0) ORDER BY s.size ASC, s.mask ASC LIMIT 1) SELECT p.point_name FROM access_points AS p JOIN best AS b ON (b.mask & p.tie_bit) <> 0 ORDER BY p.tie_bit ASC"
}
